/**
 * fonts.generated.ts — the console's vendored faces as base64 constants.
 *
 * Titillium Web (400/600/700) + Share Tech Mono (400), LATIN SUBSETS,
 * woff2, both SIL Open Font License (the license permits embedding and
 * redistribution; the game-inspired look's own commercial face is
 * deliberately NOT used). ~66KB total. Served ONLY by the HTTP host as
 * cookie-authenticated /assets/fonts/*.woff2 (CSP: font-src 'self');
 * the CLI-generated file:// page falls back to system stacks by design.
 *
 * Constant, information-free bytes — same for every user and launch,
 * like every other asset in this file's neighborhood.
 */
export const FONTS: Readonly<Record<string, string>> = {
  'tw400.woff2':
    '',
  'tw600.woff2':
    '',
  'tw700.woff2':
    '',
  'stm400.woff2':
    '',
};
